-- Customer accounts are separate from Supabase Auth so phone + password
-- does not trigger paid SMS OTP. Passwords are scrypt hashes generated by API.
create table if not exists public.customer_accounts (
  id uuid primary key default gen_random_uuid(),
  full_name text not null check (char_length(full_name) between 2 and 80),
  phone text not null unique check (phone ~ '^[6-9][0-9]{9}$'),
  password_hash text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table if not exists public.customer_sessions (
  id uuid primary key default gen_random_uuid(),
  customer_account_id uuid not null references public.customer_accounts(id) on delete cascade,
  token_hash text not null unique,
  expires_at timestamptz not null,
  created_at timestamptz not null default now()
);
alter table public.bookings add column if not exists customer_account_id uuid references public.customer_accounts(id) on delete set null;
create index if not exists bookings_customer_account_created_idx on public.bookings(customer_account_id,created_at desc);
create index if not exists customer_sessions_expiry_idx on public.customer_sessions(expires_at);
alter table public.customer_accounts enable row level security;
alter table public.customer_sessions enable row level security;
grant usage on schema public to service_role;
grant all on public.customer_accounts,public.customer_sessions to service_role;
